export function getBorderDefaults(obj) {
	
	if(!obj)
		obj = {};
	
	return $.extend(false, {
							size: 0,
							radius : 0,
							style : 'solid',
							color : '#DADFE1',
							applyTo: ['top', 'bottom', 'right', 'left'],
							radiusApplyTo: ['top_left', 'top_right', 'bottom_left', 'bottom_right']
						},
						obj);
	
	
	 
}

function getBackgroundDefaults(obj) {
	
	if(!obj)
		obj = {};
	
	return $.extend(false, defaultBackground,
						obj);
	 
}

function getBoxShadowDefaults() {
	return {
		enabled : false,
		horizontalLength : 0,
		verticalLength : 0,
		blurRadius : 5,
		spreadRadius : 0,
		color : '#000000bf'
	}
}

export function getDefaultColumnOptions() {
	return {
		id: utils.uid(),
		auto_width : true,
		size: 0,
		alignItems: 'default',
		contents : [],
		options : {
			background : defaultBackground,
			border : getBorderDefaults(),
			boxShadow : getBoxShadowDefaults(),
			padding: {
				top: 0,
				bottom: 0,
				left: 0,
				right: 0
			},
			margin: {
				top: 0,
				bottom: 0,
				left: 0,
				right: 0
			},
	    }
	}
}
